/bin/zsh -lc "python3.12 -B -c 'from solution import load_people
h=\"name,email,age,active\\n\"
valid=[(\"quoted comma\",h+\"\\\"Doe, Sam\\\",sam@example.invalid,30,true\\n\",\"Doe, Sam\"),(\"embedded newline\",h+\"\\\"Sam\\nSavage\\\",sam@example.invalid,30,true\\n\",\"Sam\\nSavage\"),(\"BOM\",\"\\ufeff\"+h+\"Sam,sam@example.invalid,30,true\\n\",\"Sam\")]
for label,s,name in valid:
 try:
  r=load_people(s); print(label, \"PASS\" if r[0][\"name\"]==name else \"FAIL\",repr(r))
 except Exception as e: print(label,\"FAIL\",type(e).__name__)
for label,s in [(\"false token\",h+\"Sam,sam@example.invalid,30,false\\n\"),(\"blank row\",h+\",,,\\n\"),(\"whitespace\",\" name , email , age , active \\n Sam , SAM@EXAMPLE.INVALID , 30 , true \\n\")]:
 try: print(label,repr(load_people(s)))
 except Exception as e: print(label,type(e).__name__)
invalid=[(\"empty input\",\"\"),(\"missing header\",\"name,email,age\\n\"),(\"duplicate header\",\"name,email,age,active,active\\n\"),(\"extra header\",\"name,email,age,active,other\\n\"),(\"extra field\",h+\"Sam,sam@example.invalid,30,true,extra\\n\"),(\"short row\",h+\"Sam,sam@example.invalid,30\\n\"),(\"empty name\",h+\",sam@example.invalid,30,true\\n\"),(\"empty email\",h+\"Sam,,30,true\\n\"),(\"multiple @\",h+\"Sam,sam@@example.invalid,30,true\\n\"),(\"email whitespace\",h+\"Sam,s am@example.invalid,30,true\\n\"),(\"missing local\",h+\"Sam,@example.invalid,30,true\\n\"),(\"missing domain\",h+\"Sam,sam@,30,true\\n\"),(\"negative age\",h+\"Sam,sam@example.invalid,-1,true\\n\"),(\"signed age\",h+\"Sam,sam@example.invalid,+1,true\\n\"),(\"large age\",h+\"Sam,sam@example.invalid,131,true\\n\"),(\"unicode age\",h+\"Sam,sam@example.invalid,٣,true\\n\"),(\"invalid active\",h+\"Sam,sam@example.invalid,30,yes\\n\"),(\"unterminated quote\",h+\"\\\"Sam,sam@example.invalid,30,true\\n\")]
n=0
for label,s in invalid:
 try: r=load_people(s); print(label,\"FAIL accepted\",repr(r))
 except Exception as e:
  ok=isinstance(e,ValueError); n+=ok; print(label,\"PASS\" if ok else \"FAIL\",type(e).__name__)
print(\"Invalid-input checks:\",n,\"/\",len(invalid),\"passed\")'"
